import React, { useState } from 'react';

/**
 * Truncate text to a maximum length with ellipsis.
 */
function truncate(text, maxLen = 120) {
  if (!text || text.length <= maxLen) return text;
  return text.slice(0, maxLen) + '…';
}

/**
 * Format similarity score as a colored percentage badge.
 */
function SimilarityBadge({ score }) {
  const pct = (score * 100).toFixed(1);
  let colorClass = 'sim-low';
  if (score >= 0.7) colorClass = 'sim-high';
  else if (score >= 0.4) colorClass = 'sim-mid';

  return <span className={`sim-badge ${colorClass}`}>{pct}%</span>;
}

/**
 * Match-type badge (citation_match vs similarity_based).
 */
function MatchTypeBadge({ type }) {
  const isCitation = type === 'citation_match';
  return (
    <span className={`match-badge ${isCitation ? 'match-citation' : 'match-similarity'}`}>
      {isCitation ? '📎 Citation Match' : '🔍 Similarity'}
    </span>
  );
}

/**
 * Expandable evidence row for a single claim.
 */
function EvidencePanel({ evidence }) {
  if (!evidence || evidence.length === 0) {
    return (
      <div className="evidence-empty">
        No matching evidence found in uploaded papers.
      </div>
    );
  }

  return (
    <div className="evidence-panel">
      {evidence.map((ev, idx) => (
        <div key={idx} className="evidence-card">
          <div className="evidence-header">
            <div className="evidence-meta">
              <span className="evidence-paper" title={ev.paper}>📄 {ev.paper}</span>
              <span className="evidence-page">Page {ev.page}</span>
              <MatchTypeBadge type={ev.match_type} />
            </div>
            <SimilarityBadge score={ev.similarity_score} />
          </div>
          <div className="evidence-text">{ev.chunk_text}</div>
        </div>
      ))}
    </div>
  );
}

/**
 * Single claim row in the results table.
 */
function ClaimRow({ claim }) {
  const [expanded, setExpanded] = useState(false);

  return (
    <>
      <tr
        className={`claim-row ${expanded ? 'claim-row-expanded' : ''}`}
        onClick={() => setExpanded(!expanded)}
      >
        <td className="claim-id-cell">
          <span className="claim-id-badge">{claim.claim_id}</span>
        </td>
        <td className="claim-text-cell" title={claim.claim_text}>
          {truncate(claim.claim_text, 160)}
        </td>
        <td className="citation-cell">
          {claim.citation_text ? (
            <span className="citation-tag">{claim.citation_text}</span>
          ) : (
            <span className="no-citation">—</span>
          )}
        </td>
        <td className="evidence-count-cell">
          {claim.evidence?.length || 0} chunk{(claim.evidence?.length || 0) !== 1 ? 's' : ''}
        </td>
        <td className="best-score-cell">
          {claim.evidence && claim.evidence.length > 0 ? (
            <SimilarityBadge score={claim.evidence[0].similarity_score} />
          ) : (
            <span className="no-citation">—</span>
          )}
        </td>
        <td className="expand-cell">
          <button className="expand-btn" title={expanded ? 'Collapse' : 'Expand'}>
            {expanded ? '▲' : '▼'}
          </button>
        </td>
      </tr>
      {expanded && (
        <tr className="evidence-row">
          <td colSpan={6}>
            <EvidencePanel evidence={claim.evidence} />
          </td>
        </tr>
      )}
    </>
  );
}

/**
 * Full analysis results component.
 * Replaces the old ResultsPlaceholder with a real claims+evidence table.
 */
function AnalysisResults({ result }) {
  return (
    <section className="section">
      <h2 className="section-title">
        <span className="icon">📊</span>
        Analysis Results
      </h2>

      {!result ? (
        <div className="results-placeholder">
          <div className="placeholder-icon">🔬</div>
          <h3>No Analysis Yet</h3>
          <p>
            Submit your literature review and reference papers above, then click
            "Analyze Literature Review" to see results.
          </p>
        </div>
      ) : (
        <div className="results-content">
          {/* Summary Bar */}
          <div className="results-summary">
            <div className="summary-stat">
              <span className="summary-value">{result.total_claims}</span>
              <span className="summary-label">Claims</span>
            </div>
            <div className="summary-stat">
              <span className="summary-value">{result.papers_analyzed}</span>
              <span className="summary-label">Papers</span>
            </div>
            <div className="summary-stat">
              <span className="summary-value">{result.total_chunks_indexed}</span>
              <span className="summary-label">Chunks Indexed</span>
            </div>
            <div className="summary-stat">
              <span className="summary-value">{result.processing_time_seconds}s</span>
              <span className="summary-label">Processing Time</span>
            </div>
          </div>

          {/* Status message */}
          <div className="result-message">
            <span className={`status-badge ${result.status}`}>● {result.status}</span>
            <span className="result-msg-text">{result.message}</span>
          </div>

          {/* Claims Table */}
          {result.claims && result.claims.length > 0 ? (
            <div className="claims-table-wrapper">
              <table className="claims-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Claim</th>
                    <th>Citation</th>
                    <th>Evidence</th>
                    <th>Best Score</th>
                    <th></th>
                  </tr>
                </thead>
                <tbody>
                  {result.claims.map((claim) => (
                    <ClaimRow key={claim.claim_id} claim={claim} />
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p style={{ textAlign: 'center', color: '#9ca3af', padding: '1rem' }}>
              No claims were extracted from the literature review.
            </p>
          )}
        </div>
      )}
    </section>
  );
}

export default AnalysisResults;
